        if col < len(grid[r]):
            v = grid[r][col]
            if v == current_color:
                current_end = r
            else:
                bars.append((current_start, r-1, current_color))
                current_color = v
                current_start = r
    if len(grid) > 0:
        bars.append((current_start, len(grid)-1, current_color))
    return bars

def apply_same_color_above_rule(grid, bg):
    """Only change bars to 5 if there's another bar of same color above in same column"""
    result = [row[:] for row in grid]
    changed_count = 0

    for c in range(len(grid[0])):
        bars = get_bars_in_column(grid, c)

        for i, (start, end, color) in enumerate(bars):
            if color == bg:
                continue

            # Check if there's another bar of same color ABOVE
            has_same_above = any(b[2] == color and b[1] < start for b in bars[:i])

            if has_same_above:
                print(f"Col {c}, bar ({start}-{end}), color {color}: has same color above -> change to 5")
                for r in range(start, end + 1):
                    if c < len(result[r]):
                        result[r][c] = 5
                changed_count += (end - start + 1)

    return result, changed_count

